"""Record narrowly scoped visual checks; raw OCR is never auto-approved."""
import hashlib,json
from pathlib import Path

ROOT=Path(__file__).resolve().parent
NEW=ROOT/'data'/'new_sources'
records=[]

def doc(filename,title,category,personnel,effective,number,rows,current=False,conditions=''):
 manifest=json.loads((NEW/'manifest.json').read_text(encoding='utf-8'))
 source=next(r for r in manifest if r['filename']==filename and r.get('downloaded'))
 records.append(dict(filename=filename,title=title,category=category,personnel=personnel,effective_from=effective,source_url=source['url'],sha256=hashlib.sha256((NEW/filename).read_bytes()).hexdigest(),number=number,current_verified=current,checked_at='2026-10-27',verification_method='assistant_visual_comparison_to_rendered_original_PDF',review_scope='เฉพาะข้อความและหน้าที่ตรวจระบุไว้; ไม่รับรองข้ออื่นหรือสิทธิรายบุคคล',conditions=conditions,excerpts=[dict(clause=c,page_number=p,text=t) for c,p,t in rows]))

doc('leave-employees-2569.pdf','ประกาศ ก.บ.ม. 1/2569 วัน เวลาปฏิบัติงาน การลา และการได้รับเงินเดือนระหว่างลาของพนักงานมหาวิทยาลัย','leave','พนักงานมหาวิทยาลัย','2026-02-13','1/2569',[
 ('10.1–10.3',3,'การลาป่วยของพนักงานมหาวิทยาลัย: ให้ขออนุญาตการลาในระบบ HCM ในวันแรกที่มาปฏิบัติงาน หากป่วยจนขอในระบบไม่ได้ ผู้รับผิดชอบระบบการลาของส่วนงาน/หน่วยงานเพิ่มรายการแทนได้ ลาป่วยตั้งแต่ 3 วันขึ้นไป ต้องมีใบรับรองแพทย์ที่ขึ้นทะเบียนและรับใบอนุญาตประกอบวิชาชีพเวชกรรมแนบใน HCM กรณีจำเป็นหรือเห็นสมควร ผู้มีอำนาจอนุญาตจะสั่งให้ใช้ใบรับรองแพทย์อื่นที่เห็นชอบแทนได้'),
 ('10.4',3,'พนักงานมหาวิทยาลัยมีสิทธิลาป่วยได้เท่าที่ป่วยจริง โดยได้รับเงินเดือนระหว่างลาปีงบประมาณหนึ่งไม่เกิน 60 วันทำการ ไม่ว่าจะครั้งเดียวหรือหลายครั้งติดต่อกัน ถ้าอธิการบดีเห็นสมควรจะจ่ายเงินเดือนต่อไปได้อีก แต่ไม่เกิน 60 วันทำการ กรณีปฏิบัติงานไม่ถึง 6 เดือนนับแต่บรรจุและแต่งตั้ง ได้รับเงินเดือนระหว่างลาป่วยไม่เกิน 30 วันทำการ และอธิการบดีอาจเห็นสมควรจ่ายต่ออีกไม่เกิน 30 วันทำการ'),
 ('11.1',3,'พนักงานมหาวิทยาลัยลาคลอดบุตรให้ขออนุญาตในระบบ HCM ก่อนหรือในวันที่ลา โดยได้รับเงินเดือนครั้งหนึ่งไม่เกิน 120 วัน ไม่ต้องมีใบรับรองแพทย์ และนับวันลาคลอดตั้งแต่วันที่คลอดบุตรเป็นต้นไป'),
 ('12.1–12.2',4,'พนักงานมหาวิทยาลัยลากิจส่วนตัวให้ขออนุญาตในระบบ HCM และได้รับอนุญาตแล้วจึงหยุดงาน เว้นแต่เหตุจำเป็นไม่อาจรออนุญาต ให้ชี้แจงในช่องความเห็น HCM แล้วหยุดไปก่อนได้ ลากิจส่วนตัวโดยได้รับเงินเดือนปีงบประมาณหนึ่งไม่เกิน 45 วันทำการ ปีแรกที่บรรจุเข้าปฏิบัติงานได้รับเงินเดือนไม่เกิน 15 วันทำการ'),
 ('12.3',4,'พนักงานมหาวิทยาลัยลากิจส่วนตัวเพื่อเลี้ยงดูบุตรที่ต่อเนื่องจากลาคลอดบุตร มีสิทธิลาไม่เกิน 150 วันทำการ โดยไม่มีสิทธิได้รับเงินเดือนระหว่างลาและไม่ได้เลื่อนเงินเดือนประจำปี'),
 ('13.1–13.2',4,'พนักงานมหาวิทยาลัยลาพักผ่อนต้องขออนุญาตใน HCM และได้รับอนุญาตแล้วจึงหยุดงานได้ มีสิทธิลาพักผ่อนปีงบประมาณหนึ่ง 10 วันทำการ กรณีเริ่มปฏิบัติงานปีแรกไม่ครบ 6 เดือน ไม่มีสิทธิลาพักผ่อนประจำปี'),
 ('13.3–13.5',4,'พนักงานมหาวิทยาลัยสะสมวันลาพักผ่อนที่เหลือรวมกับวันลาปีปัจจุบันได้ไม่เกิน 20 วันทำการ ถ้าปฏิบัติงานติดต่อกันไม่น้อยกว่า 10 ปี รวมได้ไม่เกิน 30 วันทำการ พนักงานที่เปลี่ยนสถานภาพจากข้าราชการหรือลูกจ้างประจำ นำวันลาพักผ่อนสะสมมาได้เต็มจำนวนตามสิทธิเดิม'),
 ('14.1–14.2',4,'พนักงานมหาวิทยาลัยลาไปช่วยเหลือภริยาโดยชอบด้วยกฎหมายที่คลอดบุตรได้ครั้งหนึ่งติดต่อกันไม่เกิน 15 วันทำการ โดยได้รับเงินเดือน วันลาต้องอยู่ในช่วงวันที่ภริยาลาคลอดบุตร ขอใน HCM ก่อนหรือในวันที่ลา และแสดงใบสำคัญการสมรสกับใบสูติบัตรประกอบการลาด้วย'),
],True)

doc('leave-workers-2569.pdf','ประกาศ ก.บ.ม. 2/2569 วัน เวลาปฏิบัติงาน การลา และการได้รับเงินเดือนระหว่างลาของลูกจ้างของมหาวิทยาลัย','leave','ลูกจ้างของมหาวิทยาลัย','2026-02-13','2/2569',[
 ('10.1',3,'ลูกจ้างของมหาวิทยาลัยที่ได้รับการจ้างต่อเนื่องมีสิทธิลาป่วยโดยได้รับค่าจ้างปีงบประมาณหนึ่งไม่เกิน 15 วันทำการ ต้องไม่ใช้จำนวนวันของพนักงานมหาวิทยาลัยมาแทน'),
 ('10.3–10.4',3,'ลูกจ้างของมหาวิทยาลัยลาป่วยให้ขอใน HCM ในวันแรกที่มาปฏิบัติงาน ถ้าป่วยจนขอไม่ได้ ผู้รับผิดชอบระบบของส่วนงาน/หน่วยงานเพิ่มแทนได้ ลาป่วยตั้งแต่ 3 วันขึ้นไปต้องมีใบรับรองแพทย์ผู้ขึ้นทะเบียนและมีใบอนุญาตประกอบวิชาชีพเวชกรรมแนบใน HCM กรณีจำเป็นหรือเห็นสมควร ใช้ใบรับรองแพทย์อื่นที่ผู้มีอำนาจอนุญาตเห็นชอบแทนได้'),
 ('11.1–11.2',3,'ลูกจ้างของมหาวิทยาลัยลาคลอดบุตรได้ไม่เกิน 120 วัน โดยมีสิทธิได้รับค่าจ้างระหว่างลาจากส่วนงานไม่เกิน 60 วัน กรณีเริ่มปฏิบัติงานปีงบประมาณแรกไม่ครบ 6 เดือน ไม่มีสิทธิค่าจ้างระหว่างลา ลูกจ้างรายชั่วโมงและรายวันลาคลอดได้โดยไม่ได้รับค่าจ้าง ให้นับวันลาตั้งแต่วันที่คลอดบุตร ขอใน HCM ก่อนหรือในวันที่ลา ไม่ต้องใช้ใบรับรองแพทย์ประกอบการลา'),
 ('12.1–12.2',3,'ลูกจ้างของมหาวิทยาลัยลากิจส่วนตัวปีงบประมาณหนึ่งไม่เกิน 10 วันทำการ โดยได้รับค่าจ้าง 3 วันทำการ ต้องขอใน HCM และได้รับอนุญาตก่อน เว้นแต่เหตุจำเป็นไม่อาจรอ ให้ชี้แจงเหตุผลในช่องความเห็น HCM แล้วหยุดไปก่อนได้'),
 ('13.1–13.3',4,'ลูกจ้างของมหาวิทยาลัยลาพักผ่อนโดยได้รับค่าจ้างปีงบประมาณหนึ่งไม่เกิน 10 วันทำการ เริ่มปฏิบัติงานปีแรกไม่ถึง 6 เดือนไม่มีสิทธิลาพักผ่อน ถ้าจ้างต่อเนื่องปีถัดไป สะสมรวมกับปีปัจจุบันได้ไม่เกิน 20 วันทำการ ถ้าปฏิบัติงานติดต่อกันไม่น้อยกว่า 10 ปี รวมได้ไม่เกิน 30 วันทำการ ขอใน HCM และได้รับอนุญาตแล้วจึงหยุดงานได้'),
 ('15.1–15.2',4,'ลูกจ้างของมหาวิทยาลัยลาไปช่วยเหลือภริยาโดยชอบด้วยกฎหมายที่คลอดบุตรได้ครั้งหนึ่งติดต่อกันไม่เกิน 15 วันทำการ โดยได้รับค่าจ้าง วันลาต้องอยู่ในช่วงที่ภริยาลาคลอดบุตร ขอใน HCM ก่อนหรือในวันที่ลา และแสดงใบสำคัญการสมรสและใบสูติบัตรประกอบการลา'),
],True)

doc('welfare-1605-2564.pdf','ประกาศ มข. 1605/2564 หลักเกณฑ์ อัตราการจ่ายและวิธีการจ่ายเงินสวัสดิการผู้ปฏิบัติงานในมหาวิทยาลัย','compensation','ทุกประเภท','2021-08-06','1605/2564',[
 ('เอกสารแนบท้าย ส่วน 1 ข้อ 3.1–3.2',5,'การขอเงินตรวจสุขภาพประจำปีหรือค่ารักษาพยาบาลต้องยื่นเอกสารตามแบบแนวปฏิบัติ ใช้ใบเสร็จรับเงินจากส่วนเกินค่ารักษาพยาบาลหลังเสร็จสิ้นการรักษาในคราวนั้น โดยหักสิทธิสวัสดิการอื่นที่สามารถเบิกเพิ่ม เช่น สิทธิประกันชีวิต บัตรเครดิต เรียบร้อยแล้ว กรณีอุบัติเหตุจากรถ เบิกได้เฉพาะส่วนต่างเกินสิทธิตามพระราชบัญญัติคุ้มครองผู้ประสบภัยจากรถ'),
 ('เอกสารแนบท้าย ส่วน 2 รายการ 4',6,'อัตราสนับสนุนไม่เกินต่อปีตามประกาศ 1605/2564: ค่าตรวจสุขภาพประจำปี 2,500 บาท ค่ารักษาพยาบาลผู้ป่วยใน 10,000 บาท ค่ารักษาพยาบาลผู้ป่วยนอก 2,000 บาท ต้องเป็นผู้มีสิทธิตามกองทุน ไม่ใช่ยอดเงินคงเหลือจริงของบุคคล และต้องใช้เงื่อนไขหักสิทธิอื่นประกอบ'),
 ('เอกสารแนบท้าย ส่วน 2 รายการ 2',6,'เงินสนับสนุนการศึกษาบุตรตามประกาศ 1605/2564 อัตราไม่เกินต่อปีการศึกษาต่อคน 7,000 บาท ต้องตรวจคุณสมบัติและเงื่อนไขตามกองทุนและแบบแนวปฏิบัติก่อน ไม่ใช่ยืนยันว่าบุคลากรทุกคนเบิกได้โดยอัตโนมัติ'),
 ('เอกสารแนบท้าย ส่วน 2 รายการ 3',6,'กรณีประสบภัยพิบัติ ช่วยเหลือจ่ายตามความเป็นจริงไม่เกิน 10,000 บาท และให้ยืมกรณีมูลค่าความเสียหายเกินเงินช่วยเหลือไม่เกิน 100,000 บาท ต้องเป็นผู้มีสิทธิตามเงื่อนไขกองทุนและยื่นหลักฐานตามแนวปฏิบัติ'),
 ('เอกสารแนบท้าย ส่วน 3',7,'ผู้มีสิทธิสวัสดิการต้องพิจารณาแหล่งเงินและประเภทกองทุน: พนักงานมหาวิทยาลัยเงินแผ่นดิน/เปลี่ยนสถานภาพใช้แหล่งสนับสนุนสวัสดิการและสิทธิประโยชน์ พนักงานมหาวิทยาลัยเงินรายได้/ลูกจ้างของมหาวิทยาลัยใช้แหล่งเงินรายได้ ทั้งนี้นิยามผู้ปฏิบัติงานที่มีสิทธิต้องเป็นไปตามกองทุน ห้ามสรุปสิทธิรายบุคคลจากประเภทบุคลากรเพียงอย่างเดียว'),
],True,'คำตอบเป็นอัตราทั่วไปแบบมีเงื่อนไข ต้องตรวจการมีสิทธิในกองทุนและสิทธิซ้ำซ้อนก่อนเบิกจริง')

doc('cash-advance-1026-2564.pdf','ประกาศ มข. 1026/2564 หลักเกณฑ์และแนวปฏิบัติการยืมเงินทดรองจ่ายจากเงินรายได้','travel','ข้าราชการ,ลูกจ้างประจำ,พนักงานมหาวิทยาลัย','2021-06-01','1026/2564',[
 ('12',3,'ผู้มีสิทธิยืมเงินทดรองจ่าย ได้แก่ ข้าราชการ ลูกจ้างประจำ และพนักงานมหาวิทยาลัย และต้องไม่เป็นผู้ค้างเงินยืมที่เกินกำหนดระยะเวลาในสัญญา'),
 ('17.3–17.5',5,'หลักฐานประกอบการยืมเงิน ได้แก่ โครงการ/หลักฐานที่อนุมัติให้เบิกจ่าย และแผนการใช้จ่ายแสดงวัน เวลา จำนวนเงินที่จำเป็นต้องใช้ ยื่นเรื่องถึงงานคลังหรือกลุ่มงานรับผิดชอบไม่น้อยกว่า 5 วันทำการก่อนวันที่จำเป็นต้องใช้เงิน เจ้าหน้าที่ส่วนงานตรวจและกลั่นกรอง'),
 ('20.2.1–20.2.2',5,'การส่งใช้เงินยืม: ค่าใช้จ่ายเดินทางไปราชการให้ส่งใบสำคัญคู่จ่ายเร็วที่สุดไม่เกิน 15 วันนับจากเดินทางกลับจากไปราชการ ค่าใช้จ่ายยืมเพื่อการอื่นให้ส่งใบสำคัญคู่จ่ายภายใน 30 วันนับจากวันสิ้นสุดกิจกรรม หากมีเงินเหลือต้องคืนและแนบหลักฐานตามช่องทางในประกาศ'),
],False,'ตรวจข้อความตามฉบับ; ยังไม่รับรองว่าครบฉบับแก้ไข ณ วันใช้งาน')

